from common import *
from epics import *
VER='manual test against acceptance criteria'
def doc_rows():
    d=[
     ('SECU','A02','Security','P0',"Route every approval, anywhere in the product, to an approver group and never to an individual.",
      ["Given any approval type (budget, invoice, change, request, access, status change), when it is created, then its approver is a group from the approver-group registry.","Given a rule that names a person, then the rule is rejected on save.","Given a group, then it shows members, quorum, delegates, owner and backup.","Given an approval is decided, then the decision records the deciding member and the group."],'Owner decision 1, docs: BRIEF_R16.md cross-cutting decisions.'),
     ('SECU','D05','Operations','P0',"Give every configuration item an owner, a primary support group and an approver group with decision criteria.",
      ["Given a CI record, then it has an owner: an individual for end-user devices or a group for shared infrastructure.","Given a CI, then a primary support group and an approver group with decision criteria are set.","Given a CI without these, then it appears in the ownership gap list and blocks promotion to Operational.","Given the owner changes status, then the CI ownership handover task is created."],'Owner decision 2, docs: BRIEF_R16.md.'),
     ('SECU','A01','Security','P0',"Manage permissions as one global nested model (table, then row, then attribute) in one place.",
      ["Given the permissions screen, then table, row and attribute rules are created and edited there only.","Given a screen or API reads a record, then the same engine decides access.","Given a rule change, then the preview lists affected personas before save.","Given the engine is unavailable, then access is denied, not allowed."],'Owner decision 3, docs: BRIEF_R16.md.'),
     ('SECU','S15','Experience','P0',"Show catalog items and order guides together on one portal screen for end users.",
      ["Given an end user, when the portal opens, then catalog items and order guides appear in one searchable list.","Given an order guide, then it opens a wizard that ends in one request with its items.","Given a catalog item or guide the user may not see, then it is absent.","Given the old guide screen, then it redirects to the portal."],'Owner decision 4, docs: BRIEF_R16.md.'),
     ('SECU','S23','Process','P0',"Replace 'Leaver' with 'Change status' using configurable statuses that launch the standard process, workflow, catalog item or order guide.",
      ["Given a person, when a status is chosen, then the configured launches for that status start.","Given a status definition, then it lists category, approver group, handover rule, device rule and launches.","Given statuses are edited, then the change is versioned and audited.","Given a termination status, then the leaver process runs end to end."],'Owner decision 5, docs: BRIEF_R16.md.'),
     ('SECU','X07','Experience','P0',"Place 'Why am I seeing this' in the right-aligned page-actions slot of every screen at the same position.",
      ["Given any screen, then the control is in the page-actions slot, right-aligned to the header edge.","Given a screen, then the offset from the right edge is identical to every other screen (2 px tolerance).","Given the control is used, then the popover states source rule, data, audience and owner.","Given AI text on a screen, then it appears only here or when the user asks."],'Owner decision 6, docs: BRIEF_R16.md.'),
     ('SECU','X07','Experience','P0',"Show only data-driven insight (facts, numbers, trends, deltas, chips, formula lineage); show AI prose only when asked and labeled.",
      ["Given a screen, then no unprompted AI-written sentences are shown.","Given the user asks, then AI text is labeled with model, confidence and lineage.","Given an agent name is shown, then it is 'FirstName · Role Title'.","Given a number is shown, then its formula and source are one click away."],'Standing rule, docs: BRIEF_R15.md.'),
     ('SECU','P01','Process','P1',"Give every new feature a process model, a data model with a reuse-first decision, metrics with maturity, interconnectivity and a named human owner and backup.",
      ["Given a feature proposal, then it carries a process record, an entity decision (reuse, alias or new), metrics with maturity, links to modules and owner and backup.","Given the contract check scores 4 of 4, then the feature may ship.","Given a gap, then it needs a waiver with reason, owner and expiry of 90 days at most.","Given the matrix re-scores, then regressions are shown."],'Feature contract, docs: FEATURE_CONTRACT.md.'),
    ]
    for mod,ep,cat,pri,req,acs,src in d:
        add(mod,en(ep),cat,pri,req,ac(*acs),status='Partial',verified=VER,source='docs',owner='Platform owner',backup='none named',notes=src)
    clicks=[('Request budget','budget home','1 click on the hero; top bar 1 click; deep link #new/budget-request'),('Order something','New menu','2 clicks (New, Order something); opens catalog with search focused; #new/order'),('New incident','New menu','2 clicks; form open; #new/incident'),('New change','New menu','2 clicks; form open; #new/change'),('New project demand','New menu','2 clicks; form open; #new/demand'),('New purchase order','New menu','2 clicks; form open; #new/po'),('New person','New menu','2 clicks; form open; #new/person')]
    for lab,where,path in clicks:
        add('HOME',en('S01'),'Experience','P1',f"Open the create action '{lab}' from the {where} in the stated number of clicks.",
            ac(f"Given any screen, when the user follows the path ({path}), then the form for '{lab}' is open.","Given the deep link, then the same form opens on load and on hash change.","Given the requester field, then it defaults to the signed-in user.","Given the action is also searched (new, create), then it appears in global search and the palette."),
            status='Built',verified='script b15/clicks.js (real clicks from Home)',source='docs',owner='Platform owner',backup='none named',notes='docs/CLICKPATH_R15.md')
